/*
 * Standalone logic model for the CVE-2020-24586 fragment-cache / mixed-key
 * invariant, used as an independent executable check of the ported guard.
 *
 * This is NOT a kernel build: it reproduces only the decision logic of
 * ieee80211_rx_h_defragment() (the check_sequential_pn branch) so the
 * positive path and the vulnerability-triggering negative path can be
 * executed without a kernel toolchain.
 *
 * without_fix : model of the target pre-patch code
 * with_fix    : model of the candidate code (adds entry->key_color != rx->key->color guard)
 */
#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define CCMP_PN_LEN 6
#define ACTION_DROP 0
#define ACTION_CONTINUE 1

struct key {
	unsigned int color;
	unsigned char pn[CCMP_PN_LEN];
};

struct frag_entry {
	bool check_sequential_pn;
	unsigned int key_color;
	unsigned char last_pn[CCMP_PN_LEN];
};

static int defrag_continuation(struct frag_entry *e, struct key *k, bool with_fix)
{
	unsigned char pn[CCMP_PN_LEN];
	int i;

	if (!e->check_sequential_pn)
		return ACTION_CONTINUE;

	/* requires_sequential_pn(rx, fc): CCMP/GCMP protected -> true in this model */

	if (with_fix) {
		/* candidate guard: "Prevent mixed key and fragment cache attacks" */
		if (e->key_color != k->color)
			return ACTION_DROP;
	}

	memcpy(pn, e->last_pn, CCMP_PN_LEN);
	for (i = CCMP_PN_LEN - 1; i >= 0; i--) {
		pn[i]++;
		if (pn[i])
			break;
	}
	if (memcmp(pn, k->pn, CCMP_PN_LEN))
		return ACTION_DROP;
	memcpy(e->last_pn, pn, CCMP_PN_LEN);
	return ACTION_CONTINUE;
}

static int failures;

static void expect(const char *name, bool with_fix, int got, int want)
{
	const char *verdict = (got == want) ? "PASS" : "FAIL";
	if (got != want)
		failures++;
	printf("%-58s fix=%d got=%s want=%s  %s\n", name, with_fix,
	       got == ACTION_CONTINUE ? "CONTINUE" : "DROP",
	       want == ACTION_CONTINUE ? "CONTINUE" : "DROP", verdict);
}

int main(void)
{
	unsigned char pn5[CCMP_PN_LEN] = {0, 0, 0, 0, 0, 5};
	unsigned char pn6[CCMP_PN_LEN] = {0, 0, 0, 0, 0, 6};
	unsigned char pn9[CCMP_PN_LEN] = {0, 0, 0, 0, 0, 9};
	struct key k1, k2;
	struct frag_entry e;

	memset(&k1, 0, sizeof(k1));
	memset(&k2, 0, sizeof(k2));
	k1.color = 1;
	k2.color = 2;

	/* Positive path: continuation fragment under the SAME key, sequential PN. */
	memset(&e, 0, sizeof(e));
	e.check_sequential_pn = true;
	e.key_color = k1.color;
	memcpy(e.last_pn, pn5, CCMP_PN_LEN);
	memcpy(k1.pn, pn6, CCMP_PN_LEN);
	expect("same key, sequential PN accepted", false, defrag_continuation(&e, &k1, false), ACTION_CONTINUE);
	memset(&e, 0, sizeof(e));
	e.check_sequential_pn = true;
	e.key_color = k1.color;
	memcpy(e.last_pn, pn5, CCMP_PN_LEN);
	memcpy(k1.pn, pn6, CCMP_PN_LEN);
	expect("same key, sequential PN accepted (candidate)", true, defrag_continuation(&e, &k1, true), ACTION_CONTINUE);

	/* Negative path (CVE-2020-24586): cached entry from key color 1, continuation
	 * under a DIFFERENT key whose PN happens to be sequential. Pre-patch this is
	 * accepted; the candidate guard must drop it. */
	memset(&e, 0, sizeof(e));
	e.check_sequential_pn = true;
	e.key_color = k1.color;
	memcpy(e.last_pn, pn5, CCMP_PN_LEN);
	memcpy(k2.pn, pn6, CCMP_PN_LEN);
	expect("mixed key, sequential PN (pre-patch vuln)", false, defrag_continuation(&e, &k2, false), ACTION_CONTINUE);
	memset(&e, 0, sizeof(e));
	e.check_sequential_pn = true;
	e.key_color = k1.color;
	memcpy(e.last_pn, pn5, CCMP_PN_LEN);
	memcpy(k2.pn, pn6, CCMP_PN_LEN);
	expect("mixed key, sequential PN dropped (candidate)", true, defrag_continuation(&e, &k2, true), ACTION_DROP);

	/* Preserved invariant: non-sequential PN still dropped, both before and after. */
	memset(&e, 0, sizeof(e));
	e.check_sequential_pn = true;
	e.key_color = k1.color;
	memcpy(e.last_pn, pn5, CCMP_PN_LEN);
	memcpy(k1.pn, pn9, CCMP_PN_LEN);
	expect("same key, non-sequential PN dropped (pre-patch)", false, defrag_continuation(&e, &k1, false), ACTION_DROP);
	memset(&e, 0, sizeof(e));
	e.check_sequential_pn = true;
	e.key_color = k1.color;
	memcpy(e.last_pn, pn5, CCMP_PN_LEN);
	memcpy(k1.pn, pn9, CCMP_PN_LEN);
	expect("same key, non-sequential PN dropped (candidate)", true, defrag_continuation(&e, &k1, true), ACTION_DROP);

	printf("\n%s (%d failure%s)\n", failures ? "MODEL CHECK FAILED" : "MODEL CHECK PASSED",
	       failures, failures == 1 ? "" : "s");
	return failures ? 1 : 0;
}

